//! Parity with the TypeScript reference: every vector in `vectors.json`
//! (generated by `packages/clearing/scripts/vectors.ts`), every field, with
//! both price searches.

use fairground_clearing::hash::{
    bid_set_seed_preimage, bid_set_step_preimage, commitment_preimage, parse_hex, to_hex,
};
use fairground_clearing::math::{mul_div_ceil, mul_div_floor};
use fairground_clearing::{
    Bid, ClearingResult, ClearingStatus, Fill, PriceSearch, SaleParams, clear, clear_with,
    contract_checks, prorate,
};
use serde_json::Value;

const VECTORS: &str = include_str!("vectors.json");

fn vectors() -> Value {
    serde_json::from_str(VECTORS).expect("vectors.json is valid JSON")
}

fn list<'a>(v: &'a Value, key: &str) -> &'a [Value] {
    v[key]
        .as_array()
        .unwrap_or_else(|| panic!("{key} is an array"))
}

fn amount(v: &Value) -> u128 {
    let s = v
        .as_str()
        .unwrap_or_else(|| panic!("amount string, got {v}"));
    s.parse().unwrap_or_else(|_| panic!("u128, got {s}"))
}

fn opt_amount(v: &Value) -> Option<u128> {
    (!v.is_null()).then(|| amount(v))
}

fn text(v: &Value) -> &str {
    v.as_str().unwrap_or_else(|| panic!("string, got {v}"))
}

fn opt_text(v: &Value) -> Option<&str> {
    v.as_str()
}

fn count(v: &Value) -> usize {
    usize::try_from(v.as_u64().unwrap_or_else(|| panic!("count, got {v}"))).expect("usize")
}

fn params(v: &Value) -> SaleParams {
    SaleParams {
        sale_supply: amount(&v["sale_supply"]),
        floor_price: amount(&v["floor_price"]),
        min_raise: amount(&v["min_raise"]),
        decimals: u8::try_from(count(&v["decimals"])).expect("decimals fit u8"),
        max_price: opt_amount(&v["max_price"]),
    }
}

/// `[bidder, deposit, max_price, max_spend, mismatch]`.
fn bid(v: &Value) -> Bid {
    Bid {
        bidder: text(&v[0]).to_owned(),
        deposit: amount(&v[1]),
        max_price: opt_amount(&v[2]),
        max_spend: opt_amount(&v[3]),
        mismatch: v[4].as_bool().expect("mismatch flag"),
    }
}

/// `[bidder, deposit]`: what the contract knows about a bid.
fn public_bid(v: &Value) -> Bid {
    Bid {
        bidder: text(&v[0]).to_owned(),
        deposit: amount(&v[1]),
        max_price: None,
        max_spend: None,
        mismatch: false,
    }
}

fn strings(v: &Value) -> Vec<String> {
    v.as_array()
        .expect("string list")
        .iter()
        .map(|s| text(s).to_owned())
        .collect()
}

fn hex_bytes(v: &Value) -> Vec<u8> {
    let s = text(v);
    (0..s.len() / 2)
        .map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).expect("hex"))
        .collect()
}

fn assert_result(name: &str, got: &ClearingResult, want: &Value) {
    assert_eq!(got.status.as_str(), text(&want["status"]), "{name}: status");
    assert_eq!(
        got.fail_reason.map(|r| r.as_str()),
        opt_text(&want["fail_reason"]),
        "{name}: fail_reason"
    );
    assert_eq!(
        got.clearing_price,
        amount(&want["clearing_price"]),
        "{name}: clearing_price"
    );
    assert_eq!(
        got.total_sold,
        amount(&want["total_sold"]),
        "{name}: total_sold"
    );
    assert_eq!(
        got.total_raised,
        amount(&want["total_raised"]),
        "{name}: total_raised"
    );
    assert_eq!(got.unsold, amount(&want["unsold"]), "{name}: unsold");
    assert_eq!(
        Some(got.oversubscribed),
        want["oversubscribed"].as_bool(),
        "{name}: oversubscribed"
    );
    assert_eq!(got.n_valid, count(&want["n_valid"]), "{name}: n_valid");
    assert_eq!(
        got.n_invalid,
        count(&want["n_invalid"]),
        "{name}: n_invalid"
    );
    let fills = list(want, "fills");
    assert_eq!(got.fills.len(), fills.len(), "{name}: fill count");
    for (fill, w) in got.fills.iter().zip(fills) {
        let at = format!("{name}: fill {}", fill.index);
        assert_eq!(fill.index, count(&w[0]), "{at} index");
        assert_eq!(fill.bidder, text(&w[1]), "{at} bidder");
        assert_eq!(fill.deposit, amount(&w[2]), "{at} deposit");
        assert_eq!(fill.tokens, amount(&w[3]), "{at} tokens");
        assert_eq!(fill.spent, amount(&w[4]), "{at} spent");
        assert_eq!(fill.refund, amount(&w[5]), "{at} refund");
        assert_eq!(Some(fill.valid), w[6].as_bool(), "{at} valid");
        assert_eq!(
            fill.invalid_reason.map(|r| r.as_str()),
            opt_text(&w[7]),
            "{at} invalid_reason"
        );
    }
}

#[test]
fn clearing_matches_typescript() {
    let v = vectors();
    let cases = list(&v, "clearing");
    let random = cases
        .iter()
        .filter(|c| text(&c["name"]).starts_with("random "))
        .count();
    assert!(random >= 300, "only {random} random vectors");

    let (mut settled, mut errors) = (0, 0);
    for case in cases {
        let name = text(&case["name"]);
        let p = params(&case["params"]);
        let bids: Vec<Bid> = list(case, "bids").iter().map(bid).collect();
        let got = clear(&p, &bids);
        // The sealer's fixed-shape search must give the very same result.
        assert_eq!(
            clear_with(&p, &bids, PriceSearch::FixedShape),
            got,
            "{name}: fixed-shape search"
        );
        if let Some(code) = case.get("error") {
            assert_eq!(
                got.as_ref().err().map(|e| e.code()),
                Some(text(code)),
                "{name}: error"
            );
            errors += 1;
            continue;
        }
        let got = got.unwrap_or_else(|e| panic!("{name}: unexpected error {e}"));
        assert_result(name, &got, &case["result"]);
        let checks = contract_checks(&p, &bids, &got).unwrap_or_else(|e| panic!("{name}: {e}"));
        assert_eq!(checks, strings(&case["checks"]), "{name}: contract checks");
        settled += usize::from(got.status == ClearingStatus::Settled);
    }
    assert!(
        settled > 100 && errors >= 5,
        "settled {settled}, errors {errors}"
    );
}

#[test]
fn contract_checks_match_typescript_on_tampered_results() {
    let v = vectors();
    for case in list(&v, "checks") {
        let name = text(&case["name"]);
        let p = params(&case["params"]);
        let bids: Vec<Bid> = list(case, "bids").iter().map(public_bid).collect();
        let reported = &case["result"];
        // contract_checks reads only bidder, tokens and spent of each fill.
        let fills = list(reported, "fills")
            .iter()
            .enumerate()
            .map(|(index, f)| Fill {
                index,
                bidder: text(&f[0]).to_owned(),
                deposit: 0,
                tokens: amount(&f[1]),
                spent: amount(&f[2]),
                refund: 0,
                valid: true,
                invalid_reason: None,
            })
            .collect();
        let result = ClearingResult {
            status: ClearingStatus::Settled,
            fail_reason: None,
            clearing_price: amount(&reported["clearing_price"]),
            fills,
            total_sold: 0,
            total_raised: amount(&reported["total_raised"]),
            unsold: 0,
            oversubscribed: false,
            n_valid: 0,
            n_invalid: 0,
        };
        let got = contract_checks(&p, &bids, &result).unwrap_or_else(|e| panic!("{name}: {e}"));
        assert_eq!(got, strings(&case["failed"]), "{name}");
    }
}

#[test]
fn prorate_matches_typescript() {
    let v = vectors();
    for case in list(&v, "prorate") {
        let weights: Vec<u128> = list(case, "weights").iter().map(amount).collect();
        let shares: Vec<u128> = list(case, "shares").iter().map(amount).collect();
        assert_eq!(prorate(amount(&case["amount"]), &weights), shares, "{case}");
    }
}

#[test]
fn mul_div_matches_typescript_bigints() {
    let v = vectors();
    for case in list(&v, "mul_div") {
        let (a, b, d) = (amount(&case["a"]), amount(&case["b"]), amount(&case["d"]));
        assert_eq!(
            mul_div_floor(a, b, d),
            opt_amount(&case["floor"]),
            "floor {case}"
        );
        assert_eq!(
            mul_div_ceil(a, b, d),
            opt_amount(&case["ceil"]),
            "ceil {case}"
        );
    }
}

/// Byte encodings only, so this runs without the `sha2` feature too: each
/// step's payload hash is taken from the expected preimage's last 32 bytes.
#[test]
fn bid_set_preimages_match_typescript() {
    let v = vectors();
    for case in list(&v, "bid_set_hash") {
        let sale_id = text(&case["sale_id"]);
        assert_eq!(
            to_hex(&bid_set_seed_preimage(sale_id)),
            text(&case["seed_preimage"]),
            "{sale_id}"
        );
        let steps = list(case, "steps");
        let mut prev: Option<[u8; 32]> = None;
        for (i, (b, step)) in list(case, "bids").iter().zip(steps).enumerate() {
            let want = hex_bytes(&step[0]);
            let payload_hash: [u8; 32] = want[want.len() - 32..].try_into().expect("32 bytes");
            let prev_state = prev.unwrap_or_else(|| want[..32].try_into().expect("32 bytes"));
            let index = u32::try_from(i).expect("index");
            let got = bid_set_step_preimage(
                &prev_state,
                index,
                text(&b[0]),
                amount(&b[1]),
                &payload_hash,
            )
            .expect("encodable");
            assert_eq!(got, want, "{sale_id} step {i}");
            prev = Some(parse_hex(text(&step[1])).expect("state hex"));
        }
        assert_eq!(steps.len(), list(case, "bids").len());
    }
}

#[test]
fn commitment_preimages_match_typescript() {
    let v = vectors();
    for case in list(&v, "commitment") {
        let salt: [u8; 16] = parse_hex(text(&case["salt"])).expect("16-byte salt");
        let got = commitment_preimage(
            text(&case["sale_id"]),
            text(&case["bidder"]),
            amount(&case["max_price"]),
            amount(&case["max_spend"]),
            &salt,
        );
        assert_eq!(to_hex(&got), text(&case["preimage"]), "{case}");
    }
}

#[cfg(feature = "sha2")]
mod hashed {
    use super::*;
    use fairground_clearing::hash::{BidSetEntry, BidSetHasher, bid_set_hash, commitment, sha256};

    #[test]
    fn bid_set_hash_matches_typescript() {
        let v = vectors();
        for case in list(&v, "bid_set_hash") {
            let sale_id = text(&case["sale_id"]);
            let payloads: Vec<Vec<u8>> = list(case, "bids")
                .iter()
                .map(|b| hex_bytes(&b[2]))
                .collect();
            let entries = list(case, "bids")
                .iter()
                .zip(&payloads)
                .map(|(b, payload)| BidSetEntry {
                    bidder: text(&b[0]),
                    deposit: amount(&b[1]),
                    payload,
                });
            assert_eq!(
                bid_set_hash(sale_id, entries).expect("hashable"),
                text(&case["hash"]),
                "{sale_id}"
            );

            // Step by step, the hasher's state matches every intermediate state.
            let mut hasher = BidSetHasher::new(sale_id);
            assert_eq!(hasher.state(), sha256(&bid_set_seed_preimage(sale_id)));
            for ((b, payload), step) in list(case, "bids")
                .iter()
                .zip(&payloads)
                .zip(list(case, "steps"))
            {
                hasher
                    .push(text(&b[0]), amount(&b[1]), payload)
                    .expect("hashable");
                assert_eq!(to_hex(&hasher.state()), text(&step[1]), "{sale_id}");
            }
        }
    }

    #[test]
    fn commitment_matches_typescript() {
        let v = vectors();
        for case in list(&v, "commitment") {
            let salt: [u8; 16] = parse_hex(text(&case["salt"])).expect("16-byte salt");
            let got = commitment(
                text(&case["sale_id"]),
                text(&case["bidder"]),
                amount(&case["max_price"]),
                amount(&case["max_spend"]),
                &salt,
            );
            assert_eq!(to_hex(&got), text(&case["commitment"]), "{case}");
        }
    }
}
